#!/usr/bin/python
import csv
import os
import tempfile

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INVOICES = os.path.join(BASE, 'invoices.csv')
PAYMENTS = os.path.join(BASE, 'payments.csv')
BALANCES = os.path.join(BASE, 'balances.csv')
REJECTED = os.path.join(BASE, 'rejected.csv')


def parse_cents(value):
    value = value.strip()
    if not value or value in ('+', '-'):
        raise ValueError('empty or sign-only amount')
    digits = value[1:] if value[0] in '+-' else value
    if not digits.isdigit():
        raise ValueError('amount is not an integer number of cents')
    return int(value, 10)


def publish_csv(path, fieldnames, rows):
    descriptor, temporary = tempfile.mkstemp(prefix='.' + os.path.basename(path) + '.', dir=BASE)
    try:
        with os.fdopen(descriptor, 'w', newline='') as output:
            writer = csv.DictWriter(output, fieldnames=fieldnames, lineterminator='\n')
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def main():
    invoice_order = []
    totals = {}
    with open(INVOICES, newline='') as source:
        for row in csv.DictReader(source):
            invoice_id = (row.get('invoice_id') or '').strip()
            if invoice_id in totals:
                raise ValueError('duplicate invoice_id: %s' % invoice_id)
            totals[invoice_id] = parse_cents(row.get('total_cents') or '')
            invoice_order.append(invoice_id)

    paid = dict((invoice_id, 0) for invoice_id in invoice_order)
    seen_payment_ids = set()
    rejected = []

    with open(PAYMENTS, newline='') as source:
        for row in csv.DictReader(source):
            payment_id = (row.get('payment_id') or '').strip()
            invoice_id = (row.get('invoice_id') or '').strip()
            amount_text = (row.get('amount_cents') or '').strip()

            if payment_id in seen_payment_ids:
                rejected.append({
                    'payment_id': payment_id,
                    'invoice_id': invoice_id,
                    'amount_cents': amount_text,
                    'reason': 'duplicate_payment_id',
                })
                continue
            seen_payment_ids.add(payment_id)

            try:
                amount = parse_cents(amount_text)
            except ValueError:
                rejected.append({
                    'payment_id': payment_id,
                    'invoice_id': invoice_id,
                    'amount_cents': amount_text,
                    'reason': 'malformed_amount',
                })
                continue

            if invoice_id not in totals:
                rejected.append({
                    'payment_id': payment_id,
                    'invoice_id': invoice_id,
                    'amount_cents': amount_text,
                    'reason': 'unknown_invoice_id',
                })
                continue

            paid[invoice_id] += amount

    balances = [
        {'invoice_id': invoice_id, 'outstanding_cents': totals[invoice_id] - paid[invoice_id]}
        for invoice_id in invoice_order
    ]
    publish_csv(BALANCES, ['invoice_id', 'outstanding_cents'], balances)
    publish_csv(REJECTED, ['payment_id', 'invoice_id', 'amount_cents', 'reason'], rejected)


if __name__ == '__main__':
    main()
PY_EOF
chmod 0755 "$tmp_file" && chown --reference=bin/reconcile.py "$tmp_file" && mv -f "$tmp_file" bin/reconcile.py && ./bin/reconcile.py && printf '%s\n' '--- balances.csv ---' && cat balances.csv && printf '%s\n' '--- rejected.csv ---' && cat rejected.csv && printf '%s\n' '--- source hashes after run ---' && sha256sum invoices.csv payments.csv
